89/// ## Examples
90/// For example code, please refer to the examples directory.
91pub struct ConvexClient {
92    listen_handle: Option<Arc<JoinHandle<Infallible>>>,
93    request_sender: mpsc::UnboundedSender<ClientRequest>,
94    watch_receiver: broadcast::Receiver<QueryResults>,
95}
