97/// Clone the [`ConvexClient`], sharing the connection and outstanding
98/// subscriptions.
99impl Clone for ConvexClient {
100    fn clone(&self) -> Self {
101        Self {
102            listen_handle: self.listen_handle.clone(),
103            request_sender: self.request_sender.clone(),
104            watch_receiver: self.watch_receiver.resubscribe(),
105        }
106    }
107}
