109/// Drop the [`ConvexClient`]. When the final reference to the [`ConvexClient`]
110/// is dropped, the connection is cleaned up.
111impl Drop for ConvexClient {
112    fn drop(&mut self) {
113        if let Ok(j_handle) = Arc::try_unwrap(
114            self.listen_handle
115                .take()
116                .expect("INTERNAL BUG: listen handle should never be none"),
117        ) {
118            j_handle.abort()
119        }
120    }
121}
