128    /// # #[tokio::main]
129    /// # async fn main() -> anyhow::Result<()> {
130    /// let client = ConvexClient::new("https://cool-music-123.convex.cloud").await?;
131    /// # Ok(())
132    /// # }
133    /// ```
134    pub async fn new(deployment_url: &str) -> anyhow::Result<Self> {
135        ConvexClient::new_from_builder(ConvexClientBuilder::new(deployment_url)).await
136    }
