142            .unwrap_or_else(|| format!("rust-{}", VERSION.unwrap_or("unknown")));
143        let ws_url = deployment_to_ws_url(builder.deployment_url.as_str().try_into()?)?;
144
145        // Channels for the `listen` background thread
146        let (response_sender, response_receiver) = mpsc::channel(1);
147        let (request_sender, request_receiver) = mpsc::unbounded_channel();
148
149        // Listener for when each transaction completes
150        let (watch_sender, watch_receiver) = broadcast::channel(1);
151
152        let base_client = BaseConvexClient::new();
153
154        let protocol = WebSocketManager::open(
155            ws_url,
156            response_sender,
157            builder.on_state_change,
158            client_id.as_str(),
159        )
160        .await?;
161
162        let listen_handle = tokio::spawn(worker(
163            response_receiver,
164            request_receiver,
165            watch_sender,
166            base_client,
167            protocol,
168        ));
169        let client = ConvexClient {
170            listen_handle: Some(Arc::new(listen_handle)),
171            request_sender,
172            watch_receiver,
173        };
174        Ok(client)
