198        &mut self,
199        name: &str,
200        args: BTreeMap<String, Value>,
201    ) -> anyhow::Result<QuerySubscription> {
202        let (tx, rx) = oneshot::channel();
203
204        let udf_path = name.parse()?;
205        let request = SubscribeRequest { udf_path, args };
206
207        self.request_sender.send(ClientRequest::Subscribe(
208            request,
209            tx,
210            self.request_sender.clone(),
211        ))?;
