364    ///
365    /// </div>
366    pub async fn set_auth(&mut self, token: Option<String>) {
367        let fetcher: Option<AuthTokenFetcher> = token.map(|t| {
368            Box::new(move |_force_refresh: bool| {
369                let t = t.clone();
370                Box::pin(async move { Ok(AuthenticationToken::User(t)) })
371                    as Pin<Box<dyn Future<Output = anyhow::Result<AuthenticationToken>> + Send>>
372            }) as AuthTokenFetcher
373        });
374        self.request_sender
375            .send(ClientRequest::Authenticate(fetcher))
376            .expect("INTERNAL BUG: Worker has gone away");
377    }
