380    /// functions.
381    ///
382    /// The callback is invoked immediately (with `force_refresh=false`) and
383    /// again on every websocket reconnect (with `force_refresh=true`),
384    /// allowing dynamic token refresh.
385    ///
386    /// Pass `None` to clear the callback and log out.
387    pub async fn set_auth_callback(&mut self, fetcher: Option<AuthTokenFetcher>) {
388        self.request_sender
389            .send(ClientRequest::Authenticate(fetcher))
390            .expect("INTERNAL BUG: Worker has gone away");
391    }
392
393    /// Set admin auth for use when calling Convex functions as a deployment
394    /// admin. Not typically required.
395    ///
396    /// You can get a deploy_key from the Convex dashboard's deployment settings
397    /// page. Deployment admins can act as users as part of their
398    /// development flow to see how a function would act.
399    #[doc(hidden)]
400    pub async fn set_admin_auth(
401        &mut self,
402        deploy_key: String,
403        acting_as: Option<UserIdentityAttributes>,
404    ) {
405        let fetcher: AuthTokenFetcher = Box::new(move |_force_refresh: bool| {
406            let deploy_key = deploy_key.clone();
407            let acting_as = acting_as.clone();
408            Box::pin(async move { Ok(AuthenticationToken::Admin(deploy_key, acting_as)) })
409        });
410        self.request_sender
411            .send(ClientRequest::Authenticate(Some(fetcher)))
412            .expect("INTERNAL BUG: Worker has gone away");
413    }
