416fn deployment_to_ws_url(mut deployment_url: Url) -> anyhow::Result<Url> {
417    let ws_scheme = match deployment_url.scheme() {
418        "http" | "ws" => "ws",
419        "https" | "wss" => "wss",
420        scheme => anyhow::bail!("Unknown scheme {scheme}. Expected http or https."),
421    };
