429/// A builder for creating a [`ConvexClient`] with custom configuration.
430pub struct ConvexClientBuilder {
431    deployment_url: String,
432    client_id: Option<String>,
433    on_state_change: Option<mpsc::Sender<WebSocketState>>,
434}
435
436impl ConvexClientBuilder {
437    /// Create a new [`ConvexClientBuilder`] with the given deployment URL.
438    pub fn new(deployment_url: &str) -> Self {
439        Self {
440            deployment_url: deployment_url.to_string(),
441            client_id: None,
442            on_state_change: None,
443        }
444    }
445
446    /// Set a custom client ID for this client.
447    pub fn with_client_id(mut self, client_id: &str) -> Self {
448        self.client_id = Some(client_id.to_string());
449        self
450    }
451
452    /// Set a channel to be notified of changes to the WebSocket connection
453    /// state.
454    pub fn with_on_state_change(mut self, on_state_change: mpsc::Sender<WebSocketState>) -> Self {
455        self.on_state_change = Some(on_state_change);
456        self
457    }
458
459    /// Build the [`ConvexClient`] with the configured options.
460    ///
461    /// ```no_run
462    /// # use convex::ConvexClientBuilder;
463    /// # #[tokio::main]
