465    /// let client = ConvexClientBuilder::new("https://cool-music-123.convex.cloud").build().await?;
466    /// # Ok(())
467    /// # }
468    /// ```
469    pub async fn build(self) -> anyhow::Result<ConvexClient> {
470        ConvexClient::new_from_builder(self).await
